<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigRateLimitVO;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigRateLimitAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigRateLimitAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigRateLimitAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getRateLimit returns null on a freshly created holder.
         */
        public function testRateLimitNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithSmtpOutboundConfigRateLimitAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isRateLimitAssigned());
            $this->assertNull($holder->getRateLimit());
        }
}
class ImplWithSmtpOutboundConfigRateLimitAttributeHolderUnitTest
{
  use SmtpOutboundConfigRateLimitAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRateLimitRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRateLimit();
    }}
